const METADATA_FIELD_SOURCES: ReadonlyArray<readonly [typeof GROUNDABLE_STRING_FIELDS[number], readonly string[]]> = [
    ['title', ['releaseTitle', 'trackTitle']],
    ['artistName', ['artistName']],
    ['genre', ['genre']],
    ['subGenre', ['subGenre']],
    ['mood', ['mood']],
    ['label', ['labelName']],
    ['releaseDate', ['releaseDate']],
    ['language', ['language']],
