import { describe, expect, it } from 'vitest';
import { buildReleaseCatalogRecord, type ReleaseCatalogInput } from './releaseCatalogRecord';

const INPUT: ReleaseCatalogInput = {
    ownerId: 'user-1',
    title: 'Album',
    artist: 'Artist',
    trackTitle: 'Track',
    label: 'Indii Records',
    genre: 'Electronic',
    masterAsset: {
        contentHash: 'a'.repeat(64),
        downloadUrl: 'https://firebasestorage.googleapis.com/v0/b/x/o/masters%2Fuser-1?alt=media&token=secret',
        masterFingerprint: 'SONIC-1',
        mimeType: 'audio/wav',
        originalFileName: 'master.wav',
        sizeBytes: 1,
        storagePath: 'masters/user-1/aaaa/original.wav',
        uploadedAt: '2026-01-01T00:00:00Z',
    },
    coverAsset: {
        content_hash: 'b'.repeat(64),
        download_url: 'https://firebasestorage.googleapis.com/v0/b/x/o/covers%2Fuser-1?alt=media&token=secret',
        mime_type: 'image/png',
        original_file_name: 'cover.png',
        size_bytes: 1,
        storage_path: `covers/user-1/${'b'.repeat(64)}/original.png`,
        generation_provenance: { source: 'uploaded' },
    },
};

function hasUndefined(value: unknown): boolean {
    if (value === undefined) return true;
    if (value && typeof value === 'object') return Object.values(value).some(hasUndefined);
    return false;
}

describe('buildReleaseCatalogRecord (ISSUE-1692)', () => {
    it('leaves out optional values instead of writing undefined, which Firestore rejects', () => {
        const record = buildReleaseCatalogRecord({ ...INPUT, orgId: '  ', releaseDate: ' ', isrc: '', durationSeconds: Number.NaN });

        expect(hasUndefined(record)).toBe(false);
        expect(record).not.toHaveProperty('orgId');
        expect(record.metadata).toEqual({
            releaseTitle: 'Album',
            trackTitle: 'Track',
            artistName: 'Artist',
            labelName: 'Indii Records',
            genre: 'Electronic',
            masterFingerprint: 'SONIC-1',
        });
        // No measured audio properties: format/rate/depth are not guessed.
        expect(record.assets).toEqual({
            audioStoragePath: 'masters/user-1/aaaa/original.wav',
            audioContentHash: 'a'.repeat(64),
            masterFingerprint: 'SONIC-1',
            coverArtStoragePath: `covers/user-1/${'b'.repeat(64)}/original.png`,
            coverArtContentHash: 'b'.repeat(64),
        });
    });

    it('records the release date, ISRC and organization when the artist gave them', () => {
        const record = buildReleaseCatalogRecord({ ...INPUT, orgId: 'org-7', releaseDate: '2026-12-05', isrc: ' USABC2600001 ' });

        expect(record).toMatchObject({
            userId: 'user-1',
            orgId: 'org-7',
            metadata: { releaseDate: '2026-12-05', isrc: 'USABC2600001' },
            assets: { isrc: 'USABC2600001' },
        });
    });

    it('never stores tokenized download URLs', () => {
        expect(JSON.stringify(buildReleaseCatalogRecord(INPUT))).not.toContain('token=');
    });
});

/**
 * Which workspace a release belongs to, and how to read a workspace's
 * releases under the Firestore rules (ISSUE-1695 / ISSUE-1696).
 *
 * A solo artist has no organization document: the store keeps the
 * pre-resolution placeholder `'org-default'` and an empty `organizations`
 * list. That is the personal workspace. Its releases are stored with
 * `orgId: 'personal'` (allowed by `clientIdentityFieldsMatchCaller`) and must be
 * read by `userId`, because the rules cannot prove membership of a
 * placeholder org and reject an `orgId`-only query outright.
 */
import { where, type QueryFieldFilterConstraint } from 'firebase/firestore';

export const PERSONAL_WORKSPACE_ORG_ID = 'personal';

/** Ids the app uses for "no organization": the store placeholder and the canonical personal scope. */
const PERSONAL_WORKSPACE_ALIASES: ReadonlySet<string> = new Set(['org-default', PERSONAL_WORKSPACE_ORG_ID]);

export type ReleaseWorkspace =
    | { kind: 'personal'; orgId: typeof PERSONAL_WORKSPACE_ORG_ID; userId: string }
    | { kind: 'organization'; orgId: string; userId: string };

export interface ReleaseWorkspaceInput {
    currentOrganizationId: string | null | undefined;
    organizations: ReadonlyArray<{ id: string }>;
    userId: string | null | undefined;
}

/**
 * Returns null when there is no signed-in user, or when the selected id names
 * an organization that is not loaded for this user (membership unproven), so
 * callers can refuse with a clear message instead of guessing a scope.
 */
export function resolveReleaseWorkspace({ currentOrganizationId, organizations, userId }: ReleaseWorkspaceInput): ReleaseWorkspace | null {
    const uid = userId?.trim();
    if (!uid) return null;
    const orgId = currentOrganizationId?.trim();
    if (orgId && organizations.some(org => org.id === orgId)) {
        return { kind: 'organization', orgId, userId: uid };
    }
    if (!orgId || PERSONAL_WORKSPACE_ALIASES.has(orgId) || orgId === uid) {
        return { kind: 'personal', orgId: PERSONAL_WORKSPACE_ORG_ID, userId: uid };
    }
    return null;
}

/** The one filter that lets the rules prove every returned release is readable. */
export function releaseWorkspaceFilter(workspace: ReleaseWorkspace): QueryFieldFilterConstraint {
    return workspace.kind === 'personal'
        ? where('userId', '==', workspace.userId)
        : where('orgId', '==', workspace.orgId);
}

