// Compact type scale sweep (ISSUE-1701). Usage: node scale.mjs <repoRoot> [--dry]
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(process.argv[2]);
const dry = process.argv.includes('--dry');
const src = path.join(root, 'packages/renderer/src');
const dirs = ['modules', 'components', 'core'].map(d => path.join(src, d));

// Owned by open PRs #993 / #994 — leave to them.
const SKIP = new Set([
    'modules/publishing/components/ReleaseWizard.tsx',
    'modules/distribution/components/ConnectDistributorModal.tsx',
    'modules/finance/components/ExpenseManualEntryModal.tsx',
    'modules/publicist/components/CampaignDetailsModal.tsx',
    'modules/touring/components/DaySheetModal.tsx',
    'modules/publicist/components/ReleaseKitModal.tsx',
    'modules/creative/components/FreeMiniCampaignModal.tsx',
    'modules/social/components/AccountCreationWizard.tsx',
]);

const BIG = '(?:3xl|4xl|5xl|6xl|7xl|8xl|9xl)';
const RESP = '(?:sm|md|lg|xl|2xl):';
const files = [];
const walk = d => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
        const p = path.join(d, e.name);
        if (e.isDirectory()) walk(p);
        else if (/\.tsx$/.test(e.name) && !/\.(test|stories)\.tsx$/.test(e.name)) files.push(p);
    }
};
dirs.forEach(walk);

let changedFiles = 0, changedLines = 0;
const report = [];
for (const f of files) {
    const rel = path.relative(src, f);
    if (SKIP.has(rel)) continue;
    const lines = fs.readFileSync(f, 'utf8').split('\n');
    let touched = false;
    const out = lines.map(line => {
        // Faint decorative glyphs behind cards stay as they are.
        if (/opacity-(5|10|20)\b/.test(line) && new RegExp(`\\btext-${BIG}\\b`).test(line)) return line;
        let next = line;
        const isFounders = rel === 'modules/founders/FoundersCheckout.tsx';
        if (/<h[12]\b/.test(line)) {
            const target = isFounders ? 'text-3xl' : 'text-xl';
            next = next
                .replace(new RegExp(`\\s?\\b${RESP}text-(?:xl|2xl|${BIG.slice(3, -1)})\\b`, 'g'), '')
                .replace(new RegExp(`\\btext-(?:2xl|${BIG.slice(3, -1)})\\b`, 'g'), target);
        } else if (/<h3\b/.test(line)) {
            next = next
                .replace(new RegExp(`\\s?\\b${RESP}text-(?:xl|2xl|${BIG.slice(3, -1)})\\b`, 'g'), '')
                .replace(new RegExp(`\\btext-(?:xl|2xl|${BIG.slice(3, -1)})\\b`, 'g'), 'text-base');
        } else {
            next = next
                .replace(new RegExp(`\\s?\\b${RESP}text-${BIG}\\b`, 'g'), '')
                .replace(new RegExp(`\\btext-${BIG}\\b`, 'g'), 'text-2xl');
        }
        if (next !== line) { touched = true; changedLines++; }
        return next;
    });
    if (touched) {
        changedFiles++;
        report.push(rel);
        if (!dry) fs.writeFileSync(f, out.join('\n'));
    }
}
console.log(`${dry ? '[dry] ' : ''}${changedFiles} files, ${changedLines} lines`);
console.log(report.join('\n'));

