import React from 'react';
import { ModuleErrorBoundary } from '@/core/components/ModuleErrorBoundary';
import { AdaptiveWorkspace } from './AdaptiveWorkspace';

export interface ThreePanelDashboardProps {
    /** The name of the module for the error boundary (e.g. "Finance") */
    moduleName: string;

    /** The icon element for the header (e.g. <TrendingUp size={18} className="text-white" />) */
    headerIcon: React.ReactNode;

    /** Display title for the dashboard header */
    title: string;

    /** Subtitle for the dashboard header */
    subtitle: string;

    /** Full tailwind class for the background blur (e.g. "bg-blue-500/8") */
    bgBlobClass: string;

    /** Full tailwind class for the icon background (e.g. "bg-linear-to-br from-blue-500 to-blue-400") */
    iconBgClass: string;

    /** Full tailwind class for the icon shadow (e.g. "shadow-blue-500/20") */
    iconShadowClass: string;

    /** Left sidebar content */
    leftPanel: React.ReactNode;

    /** Right sidebar content */
    rightPanel?: React.ReactNode;

    /** Header-level actions (buttons/menus), right-aligned beside the title.
     *  ISSUE-1441: modules forked the header markup to get action buttons —
     *  this slot removes the reason to fork. */
    actions?: React.ReactNode;

    /** Center content (placed directly under the header in the flex-1 container) */
    children: React.ReactNode;
}

/**
 * ThreePanelDashboard
 * 
 * Abstracted unified layout skeleton for Three-Panel modules (Legal, Finance, Licensing).
 * Enforces rigid structural consistency across modules while accepting highly cohesive
 * customized theming via tailwind class injections to prevent JIT pruning.
 */
export function ThreePanelDashboard({
    moduleName,
    headerIcon,
    title,
    subtitle,
    bgBlobClass,
    iconBgClass,
    iconShadowClass,
    leftPanel,
    rightPanel,
    actions,
    children
}: ThreePanelDashboardProps) {
    return (
        <ModuleErrorBoundary moduleName={moduleName}>
            <AdaptiveWorkspace
                className="bg-bg-dark text-white"
                leftRail={leftPanel}
                rightRail={rightPanel}
                leftRailLabel={`${moduleName} navigation`}
                rightRailLabel={`${moduleName} details`}
            >
                <div className="flex-1 flex flex-col min-w-0">
                    {/* Header */}
                    <div data-testid={`${moduleName.toLowerCase()}-header`} className="px-4 md:px-6 h-12 border-b border-white/5 flex items-center flex-shrink-0 relative bg-[#0c0c12]/80 backdrop-blur-xl z-20">
                        <div className={`absolute top-[-80px] left-[-80px] w-[300px] h-[300px] blur-[100px] pointer-events-none rounded-full ${bgBlobClass}`} />
                        <div className="relative z-10 flex items-center gap-3 w-full min-w-0">
                            <div className={`w-6 h-6 rounded-md flex items-center justify-center shadow-md shrink-0 ${iconBgClass} ${iconShadowClass}`}>
                                {headerIcon}
                            </div>
                            <div className="flex items-baseline gap-2.5 min-w-0">
                                <h1 className="text-sm font-black text-white tracking-tight uppercase whitespace-nowrap">{title}</h1>
                                <p className="text-muted-foreground font-medium tracking-wide text-[10px] truncate hidden sm:block">{subtitle}</p>
                            </div>
                            {actions && (
                                <div className="ml-auto flex items-center gap-2 shrink-0">{actions}</div>
                            )}
                        </div>
                    </div>

                    {/* Content (Tabs / Main feed) */}
                    <div className="flex-1 flex flex-col overflow-hidden">
                        {children}
                    </div>
                </div>
            </AdaptiveWorkspace>
        </ModuleErrorBoundary>
    );
}

