// Compact spacing sweep (ISSUE-1704). node compact.mjs <repoRoot> [--dry] [--report]
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(process.argv[2]);
const dry = process.argv.includes('--dry');
const report = process.argv.includes('--report');
const src = path.join(root, 'packages/renderer/src');

// Surfaces that must keep their own scale: touch-first mobile remote, onboarding
// and the Founders sales page, public fan/share pages, and image/share exports.
const SKIP_DIRS = ['modules/mobile-remote/', 'modules/onboarding/', 'modules/founders/', 'components/share/'];
const SKIP_FILES = new Set([
    'modules/marketing/components/PreSaveLandingPage.tsx',
    'modules/knowledge/KnowledgeBase.tsx',
    'modules/knowledge/components/DocumentCard.tsx',
    'modules/notes/NotesModule.tsx',
    'modules/workflow/WorkflowLab.tsx',
]);

