// Jev copy triage against directives/brand_voice_and_copy.md (advisory).
// node jev-copy.mjs <envFile> <outJson> <file...>
import fs from 'node:fs';

const [envFile, outFile, ...files] = process.argv.slice(2);
const env = fs.readFileSync(envFile, 'utf8');
const KEY = (env.match(/^TYPESAFE_API_KEY=(.*)$/m)?.[1] ?? '').trim().replace(/^['"]|['"]$/g, '');
if (!KEY) { console.error('TYPESAFE_API_KEY missing'); process.exit(1); }

const ENDPOINT = 'https://api.typesafe.ai/v1/systemone';

// Visible copy: JSX text nodes and common copy props / object fields.
const items = [];
const seen = new Set();
for (const f of files) {
    const lines = fs.readFileSync(f, 'utf8').split('\n');
    lines.forEach((line, i) => {
        const found = [];
        for (const m of line.matchAll(/>\s*([^<>{}]*[A-Za-z]{3,}[^<>{}]*?)\s*</g)) found.push(m[1]);
        for (const m of line.matchAll(/\b(?:title|placeholder|label|description|message|subtitle|text)\s*[:=]\s*["'`]([^"'`]{4,})["'`]/g)) found.push(m[1]);
        const solo = line.trim();
        if (/^[A-Z][^<>{}=;()]{6,}$/.test(solo) && !/^(import|export|const|let|return|type|interface)\b/.test(solo)) found.push(solo);
        for (const t of found) {
            const text = t.trim();
            if (text.length < 4 || /^[\w.-]+$/.test(text) && !/\s/.test(text) && text.length < 12) continue;
            const k = text.toLowerCase();
            if (seen.has(k)) continue;
            seen.add(k);
            items.push({ file: f, line: i + 1, text });
        }
    });
}

const CRITERIA = {
    clean: 'Plain, direct copy a musician would hear from a friend. Nothing to change.',
    ai_hype: 'Mentions "AI", agents as AI, or neon/cyberpunk tech hype (neural, vectors, intelligence base, engine, synthesis).',
    plumbing: 'Exposes internal plumbing: model or vendor names, protocol names (DDEX, Gemini, Vertex), internal ticket or judgment numbers, latency figures, or code identifiers.',
    aggressive_or_mystical: 'War-room aggression (supremacy, command, swarm) or tech-spiritualism (DNA, alchemy, life force, soul).',
    jargon_or_verbose: 'Over-explains or uses corporate jargon where a few plain words would do (e.g. "calibrating all 40 faders", "posture axes").',
};

async function judge(batch) {
    const questions = {};
    batch.forEach((it, n) => {
        questions[`q${n}`] = {
            type: 'choice',
            instructions: {
                task: 'This is one piece of on-screen copy from a music-business app for independent artists. The brand voice is direct, human and grounded; it bans the word AI, hype, exposed plumbing, aggression and mystical jargon. Classify the copy.',
                copy: it.text,
            },
            criteria: CRITERIA,
        };
    });
    const res = await fetch(ENDPOINT, {
        method: 'POST',
        headers: { Authorization: `Bearer ${KEY}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ state: { app: 'indii studio settings and pages' }, questions, model: 'jev-latest' }),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${(await res.text()).slice(0, 300)}`);
    return res.json();
}

const out = [];
let tin = 0, tout = 0, calls = 0;
for (let i = 0; i < items.length; i += 25) {
    const batch = items.slice(i, i + 25);
    const json = await judge(batch);
    calls++;
    tin += json.usage?.input_tokens ?? 0;
    tout += json.usage?.output_tokens ?? 0;
    batch.forEach((it, n) => {
        const a = json.answers?.[`q${n}`];
        out.push({ ...it, verdict: a?.choice ?? 'error', confidence: a?.confidence ?? null });
    });
}
fs.writeFileSync(outFile, JSON.stringify(out, null, 2));
const flagged = out.filter(o => o.verdict !== 'clean' && (o.confidence ?? 0) >= 0.65);
console.log(`items ${items.length}, calls ${calls}, tokens in ${tin} out ${tout}, flagged ${flagged.length}`);
for (const f of flagged) console.log(`${f.verdict} ${(f.confidence ?? 0).toFixed(2)} ${f.file.replace(/.*src\//, '')}:${f.line} | ${f.text.slice(0, 110)}`);

