4:export const CREATIVE_ASSET_MIME = 'application/x-indii-creative-asset+json';
16:export interface CreativeAssetDragPayload {
17:    version: 1;
18:    kind: 'creative-asset';
19:    source: CreativeAssetDragSource;
20:    asset: {
21:        id: string;
22:        type: CreativeAssetType;
23:        url: string;
24:        storageUri?: string;
25:        thumbnailUrl?: string;
26:        name: string;
27:        prompt: string;
28:        projectId?: string;
29:        parentId?: string;
35:function isObject(value: unknown): value is Record<string, unknown> {
39:function isAssetType(value: unknown): value is CreativeAssetType {
48:function isDragSource(value: unknown): value is CreativeAssetDragSource {
58:function isSafeAssetUrl(value: string): boolean {
59:    return /^(https?:\/\/|gs:\/\/|blob:|file:\/\/)/i.test(value)
60:        || /^data:(image|video|audio)\/[a-z0-9.+-]+[;,]/i.test(value);
        dataTransfer.setData('image/url', payload.asset.url);
        dataTransfer.setData('image/name', payload.asset.name);
    }
    dataTransfer.effectAllowed = effectAllowed;
    return payload;
}

export function readCreativeAssetDrag(dataTransfer: DataTransfer): CreativeAssetDragPayload | null {
    const canonical = dataTransfer.getData(CREATIVE_ASSET_MIME);
    if (canonical) {
        const parsed = parsePayload(safeParseJson(canonical));
        if (parsed) return parsed;
    }

    const applicationJson = dataTransfer.getData('application/json');
    if (applicationJson) {
        const legacy = safeParseJson(applicationJson);
        if (isObject(legacy) && legacy.type === 'asset' && isObject(legacy.asset)) {
            const asset = legacy.asset;
            const parsed = parsePayload({
                version: 1,
                kind: 'creative-asset',
                source: 'unknown',
                asset: {
                    id: typeof asset.id === 'string' ? asset.id : `legacy-${Date.now()}`,
                    type: asset.type === 'audio' ? 'music' : asset.type,
                    url: asset.url,
                    storageUri: asset.storageUri,
                    name: typeof asset.name === 'string' ? asset.name : 'Dropped asset',
                    prompt: typeof asset.name === 'string' ? asset.name : 'Dropped asset',
                },
            });
            if (parsed) return parsed;
        }
    }

    // Creative Clipboard historically placed a complete asset object in text/plain.
    const plainText = dataTransfer.getData('text/plain');
    if (plainText.startsWith('{')) {
        const legacy = safeParseJson(plainText);
        if (isObject(legacy)) {
            return parsePayload({
                version: 1,
                kind: 'creative-asset',
                source: 'creative-clipboard',
                asset: {
                    id: legacy.id,
                    type: legacy.type,
                    url: legacy.url,
                    storageUri: legacy.storageUri,
                    thumbnailUrl: legacy.thumbnailUrl,
        bg-white/[0.03] border border-dashed rounded-xl p-5 text-center transition-colors
        ${assets.coverArt ? 'border-dept-publishing/40 bg-dept-publishing/5' : 'border-white/15 hover:border-white/30'}
      `}
        onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
        onDrop={async (e) => {
          e.preventDefault();
          const creative = readCreativeAssetDrag(e.dataTransfer);
          if (creative && creative.asset.type === 'image') {
            try {
              await uploadCoverByUrl(creative.asset.url);
            } catch (err: unknown) {
              logger.error('Cover art drop failed:', err);
            }
          }
        }}
      >
        {assets.coverArt ? (
          <div className="flex flex-col items-center">
            <div className="w-12 h-12 mx-auto rounded-lg mb-3 overflow-hidden border border-white/10">
              <img src={assets.coverArt.url} alt="Cover Art" className="w-full h-full object-cover" />
            </div>
            <h3 className="text-sm font-bold text-white mb-1">Cover Art Uploaded</h3>
            <p className="text-xs text-gray-400 mb-3">{assets.coverArt.width}x{assets.coverArt.height} • {(assets.coverArt.sizeBytes / (1024 * 1024)).toFixed(2)} MB</p>
            <button
              onClick={() => updateAssets({ coverArt: undefined })}
              className="text-xs font-bold uppercase tracking-widest text-red-400 hover:text-red-300"
            >
              Replace Image
            </button>
          </div>
        ) : (
          <>
            <div className="w-10 h-10 mx-auto bg-white/5 rounded-lg mb-3 flex items-center justify-center">
              <Music size={24} className="text-gray-500" />
            </div>
            <h3 className="text-sm font-bold text-white mb-1">Upload Cover Art</h3>

