const d=()=>document.querySelector('[role=dialog]'); const wait=ms=>new Promise(r=>setTimeout(r,ms));
const cb=[...d().querySelectorAll('input[type=checkbox]')][0]; cb.click(); await wait(500);
const inp=[...d().querySelectorAll('input[type=text]')][0];
const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;
let typed=''; for(const ch of 'Flow Music (flowmusic.app)'){ typed+=ch; setter.call(inp,typed); inp.dispatchEvent(new Event('input',{bubbles:true})); await wait(30); }
await wait(300);
({field: inp.value, expected: 'Flow Music (flowmusic.app)', same: inp.value==='Flow Music (flowmusic.app)'})

