const zone=[...document.querySelectorAll('[role=dialog] *')].find(e=>{const k=Object.keys(e).find(k=>k.startsWith('__reactProps')); return k && e[k].onDrop;});
const img=[...document.querySelectorAll('img')].find(i=>i.naturalWidth===1276 && i.getBoundingClientRect().x>1100);
const tile=img.closest('[draggable="true"]'); const dt=new DataTransfer();
tile.dispatchEvent(new DragEvent('dragstart',{bubbles:true,cancelable:true,dataTransfer:dt}));
const k=Object.keys(zone).find(k=>k.startsWith('__reactProps'));
await zone[k].onDrop({preventDefault(){}, stopPropagation(){}, dataTransfer: dt});
tile.dispatchEvent(new DragEvent('dragend',{bubbles:true,cancelable:true,dataTransfer:dt}));
await new Promise(r=>setTimeout(r,6000));
const d=document.querySelector('[role=dialog]'); const alert=d.querySelector('[data-testid="release-assets-error"]');
({cover:(d.innerText.match(/Cover Art Uploaded\s+([^\n]+)/)||[])[1], reason: alert?.innerText, nextDisabled:[...d.querySelectorAll('button')].find(b=>b.textContent.trim()==='Next')?.disabled})

